// PR claim: "renderer 6% faster — one run before/after: 412µs -> 388µs"

func BenchmarkRenderInvoice(b *testing.B) {
	for i := 0; i < b.N; i++ {
		data, err := loadFixture("testdata/invoice.json") // reads and unmarshals the file
		if err != nil {
			b.Fatal(err)
		}
		out := RenderInvoice(data)
		_ = out
	}
}
